import { memo, useCallback, useMemo } from 'react';
import { useIntl } from 'react-intl';

import { TemplateSlide } from 'components';
import { TableOfContents } from 'components/TableOfContents';
import { useAssetHost } from 'config/api';
import { useVolumePagesKpi } from 'pages/pillars/ValueCreation/VolumePages/contexts';
import { StyledExportPageSection } from 'shared/Styles/exportPages.styles';

import { pageSections, SUMMARY_TOC_MESSAGE_IDS } from '../../constants';
import { useSummaryTocGroups } from '../../hooks';
import {
  StyledSummaryTocCardHeader,
  StyledSummaryTocCardHeaderFlag,
  StyledSummaryTocCardHeaderTitle,
} from './SummaryAgendaSection.styles';
import { SummaryAgendaSectionProps } from './types';

export const SummaryAgendaSection = memo(
  ({ getPageByName, dataTestId }: SummaryAgendaSectionProps) => {
    const { formatMessage } = useIntl();
    const { kpiName } = useVolumePagesKpi();
    const assetHost = useAssetHost();
    const tocGroups = useSummaryTocGroups(getPageByName);

    const cardHeader = useMemo(
      () => (
        <StyledSummaryTocCardHeader
          data-testid={
            dataTestId ? `${dataTestId}-agenda-toc-card-header` : undefined
          }
        >
          <StyledSummaryTocCardHeaderFlag
            src={`${assetHost}/countries/rounded_flags/ABI.png`}
            alt="Global flag"
          />
          <StyledSummaryTocCardHeaderTitle>
            {formatMessage(
              { id: SUMMARY_TOC_MESSAGE_IDS.globalKpiResults },
              { kpiName },
            )}
          </StyledSummaryTocCardHeaderTitle>
        </StyledSummaryTocCardHeader>
      ),
      [assetHost, dataTestId, formatMessage, kpiName],
    );

    const handleTocItemClick = useCallback((slideId: string) => {
      document
        .querySelector(`[data-page-name="${slideId}"]`)
        ?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }, []);

    return (
      <StyledExportPageSection data-page-name={pageSections.agenda}>
        <TemplateSlide
          enablePngCopy
          title=""
          page={getPageByName(pageSections.agenda)?.index}
          headerDivider={false}
          dataTestId={
            dataTestId ? `${dataTestId}-${pageSections.agenda}` : undefined
          }
        >
          <TableOfContents
            title={formatMessage({
              id: SUMMARY_TOC_MESSAGE_IDS.tableOfContents,
            })}
            cardHeader={cardHeader}
            groups={tocGroups}
            onItemClick={handleTocItemClick}
            dataTestId={dataTestId ? `${dataTestId}-agenda-toc` : undefined}
          />
        </TemplateSlide>
      </StyledExportPageSection>
    );
  },
);

SummaryAgendaSection.displayName = 'SummaryAgendaSection';
